insert into public.recipes
  (name, meal_type, cuisine, calories, protein_g, carbs_g, fat_g, fiber_g, prep_minutes, cook_minutes, servings, dietary_tags, allergens, ingredients, instructions, storage_instructions, photo_url, status)
values
('Tofu Green Curry with Brown Rice', 'dinner', 'thai', 518, 28, 52, 22, 8, 15, 20, 1, array['vegan', 'vegetarian', 'high-protein', 'gluten-free'], array['soybeans'], '[{"name":"Extra-firm tofu","quantity":7,"unit":"oz","section":"protein"},{"name":"Green curry paste","quantity":2,"unit":"tbsp","section":"pantry"},{"name":"Light coconut milk","quantity":0.75,"unit":"cup","section":"pantry"},{"name":"Cooked brown rice","quantity":1,"unit":"cup","section":"grains"},{"name":"Broccoli florets","quantity":1,"unit":"cup","section":"produce"},{"name":"Red bell pepper","quantity":1,"unit":"each","section":"produce"},{"name":"Tamari","quantity":1,"unit":"tbsp","section":"pantry"},{"name":"Lime","quantity":0.5,"unit":"each","section":"produce"}]'::jsonb, array['Press the tofu, cut into cubes, and sear in a hot nonstick pan until golden on two sides.', 'Add curry paste and a splash of coconut milk, stirring until fragrant.', 'Add the remaining coconut milk, broccoli, and bell pepper; simmer 8-10 minutes until tender.', 'Season with tamari and lime juice, and serve over the brown rice.'], 'Keeps 3 days refrigerated; store rice separately if possible.', null, 'active'),
('Lentil Bolognese with Spaghetti', 'dinner', 'italian', 524, 26, 78, 12, 14, 10, 30, 1, array['vegan', 'vegetarian', 'high-protein'], array['wheat'], '[{"name":"Dry spaghetti","quantity":2.5,"unit":"oz","section":"grains"},{"name":"Cooked brown or green lentils","quantity":1,"unit":"cup","section":"protein"},{"name":"Crushed tomatoes","quantity":1,"unit":"cup","section":"pantry"},{"name":"Yellow onion","quantity":0.5,"unit":"each","section":"produce"},{"name":"Carrot","quantity":1,"unit":"each","section":"produce"},{"name":"Garlic","quantity":2,"unit":"cloves","section":"produce"},{"name":"Olive oil","quantity":1.5,"unit":"tsp","section":"pantry"},{"name":"Italian herbs","quantity":1,"unit":"tsp","section":"pantry"}]'::jsonb, array['Cook the spaghetti in salted water per the package.', 'Soften diced onion, carrot, and garlic in olive oil, 5-6 minutes.', 'Add lentils, crushed tomatoes, and herbs; simmer 15 minutes until thick.', 'Toss with the drained pasta and a splash of pasta water.'], 'Sauce keeps 4 days refrigerated and freezes well.', null, 'active'),
('Chickpea Coconut Curry', 'dinner', 'indian', 524, 19, 58, 24, 13, 10, 25, 1, array['vegan', 'vegetarian', 'gluten-free'], array[]::text[], '[{"name":"Canned chickpeas","quantity":1,"unit":"cup","section":"protein"},{"name":"Light coconut milk","quantity":0.75,"unit":"cup","section":"pantry"},{"name":"Diced tomatoes","quantity":0.75,"unit":"cup","section":"pantry"},{"name":"Cooked basmati rice","quantity":0.75,"unit":"cup","section":"grains"},{"name":"Baby spinach","quantity":2,"unit":"cups","section":"produce"},{"name":"Curry powder","quantity":1.5,"unit":"tbsp","section":"pantry"},{"name":"Yellow onion","quantity":0.5,"unit":"each","section":"produce"}]'::jsonb, array['Soften the diced onion, then bloom the curry powder for 30 seconds.', 'Add chickpeas, tomatoes, and coconut milk; simmer 15 minutes.', 'Wilt in the spinach at the end and serve over rice.'], 'Keeps 4 days refrigerated; flavor improves overnight.', null, 'active'),
('Black Bean Sweet Potato Bowl', 'dinner', 'mexican', 504, 18, 72, 16, 16, 10, 30, 1, array['vegan', 'vegetarian', 'gluten-free'], array[]::text[], '[{"name":"Sweet potato","quantity":1,"unit":"large","section":"produce"},{"name":"Canned black beans","quantity":0.75,"unit":"cup","section":"protein"},{"name":"Cooked rice","quantity":0.5,"unit":"cup","section":"grains"},{"name":"Avocado","quantity":0.5,"unit":"each","section":"produce"},{"name":"Salsa","quantity":0.25,"unit":"cup","section":"pantry"},{"name":"Cumin","quantity":1,"unit":"tsp","section":"pantry"},{"name":"Lime","quantity":0.5,"unit":"each","section":"produce"}]'::jsonb, array['Roast cubed sweet potato with cumin at 425°F for 25-30 minutes.', 'Warm the black beans with a pinch of salt.', 'Assemble over rice with avocado, salsa, and a squeeze of lime.'], 'Components keep 4 days refrigerated; add avocado fresh.', null, 'active'),
('Teriyaki Tempeh Stir-fry', 'dinner', 'japanese', 474, 30, 48, 18, 9, 10, 15, 1, array['vegan', 'vegetarian', 'high-protein', 'quick'], array['soybeans', 'wheat', 'sesame'], '[{"name":"Tempeh","quantity":4,"unit":"oz","section":"protein"},{"name":"Teriyaki sauce","quantity":2,"unit":"tbsp","section":"pantry"},{"name":"Soy sauce","quantity":1,"unit":"tsp","section":"pantry"},{"name":"Cooked white rice","quantity":0.75,"unit":"cup","section":"grains"},{"name":"Snap peas","quantity":1,"unit":"cup","section":"produce"},{"name":"Carrot","quantity":1,"unit":"each","section":"produce"},{"name":"Sesame oil","quantity":1,"unit":"tsp","section":"pantry"},{"name":"Scallions","quantity":2,"unit":"each","section":"produce"}]'::jsonb, array['Sear sliced tempeh in sesame oil until browned on both sides.', 'Add snap peas and carrot; stir-fry 3-4 minutes.', 'Glaze with teriyaki and soy sauce, and serve over rice with scallions.'], 'Keeps 3 days refrigerated.', null, 'active'),
('White Bean Mushroom Ragout with Polenta', 'dinner', 'mediterranean', 454, 20, 62, 14, 12, 10, 25, 1, array['vegan', 'vegetarian', 'gluten-free'], array[]::text[], '[{"name":"Cannellini beans","quantity":0.75,"unit":"cup","section":"protein"},{"name":"Cremini mushrooms","quantity":1.5,"unit":"cups","section":"produce"},{"name":"Instant polenta","quantity":0.33,"unit":"cup","section":"grains"},{"name":"Crushed tomatoes","quantity":0.5,"unit":"cup","section":"pantry"},{"name":"Garlic","quantity":2,"unit":"cloves","section":"produce"},{"name":"Olive oil","quantity":2,"unit":"tsp","section":"pantry"},{"name":"Fresh thyme","quantity":1,"unit":"tsp","section":"produce"}]'::jsonb, array['Brown the mushrooms hard in olive oil before salting.', 'Add garlic, beans, tomatoes, and thyme; simmer 10 minutes.', 'Cook the polenta per the package and spoon the ragout over it.'], 'Keeps 3 days refrigerated; loosen polenta with water when reheating.', null, 'active'),
('Peanut Noodle Bowl with Edamame', 'lunch', 'chinese', 508, 24, 58, 20, 9, 15, 10, 1, array['vegan', 'vegetarian', 'high-protein', 'make-ahead'], array['peanuts', 'wheat', 'soybeans', 'sesame'], '[{"name":"Lo mein noodles","quantity":2.5,"unit":"oz","section":"grains"},{"name":"Shelled edamame","quantity":0.75,"unit":"cup","section":"protein"},{"name":"Peanut butter","quantity":1.5,"unit":"tbsp","section":"pantry"},{"name":"Soy sauce","quantity":1,"unit":"tbsp","section":"pantry"},{"name":"Rice vinegar","quantity":1,"unit":"tbsp","section":"pantry"},{"name":"Sesame oil","quantity":0.5,"unit":"tsp","section":"pantry"},{"name":"Shredded cabbage","quantity":1,"unit":"cup","section":"produce"},{"name":"Cucumber","quantity":0.5,"unit":"each","section":"produce"}]'::jsonb, array['Cook the noodles and edamame; rinse under cold water.', 'Whisk peanut butter, soy sauce, vinegar, and sesame oil with a splash of warm water.', 'Toss everything with the cabbage and cucumber.'], 'Keeps 3 days refrigerated — an ideal make-ahead lunch.', null, 'active'),
('Mediterranean Quinoa Salad', 'lunch', 'mediterranean', 446, 16, 55, 18, 10, 15, 15, 1, array['vegan', 'vegetarian', 'gluten-free', 'make-ahead'], array[]::text[], '[{"name":"Dry quinoa","quantity":0.5,"unit":"cup","section":"grains"},{"name":"Canned chickpeas","quantity":0.5,"unit":"cup","section":"protein"},{"name":"Cherry tomatoes","quantity":0.75,"unit":"cup","section":"produce"},{"name":"Cucumber","quantity":0.5,"unit":"each","section":"produce"},{"name":"Kalamata olives","quantity":8,"unit":"each","section":"pantry"},{"name":"Olive oil","quantity":2,"unit":"tsp","section":"pantry"},{"name":"Lemon","quantity":0.5,"unit":"each","section":"produce"},{"name":"Fresh parsley","quantity":0.25,"unit":"cup","section":"produce"}]'::jsonb, array['Cook the quinoa and let it cool slightly.', 'Toss with chickpeas, chopped vegetables, olives, and parsley.', 'Dress with olive oil, lemon juice, salt, and pepper.'], 'Keeps 4 days refrigerated; dress just before eating if making ahead.', null, 'active'),
('Smoky Tofu Burrito Bowl', 'lunch', 'mexican', 488, 26, 60, 16, 12, 10, 15, 1, array['vegan', 'vegetarian', 'gluten-free', 'high-protein'], array['soybeans'], '[{"name":"Extra-firm tofu","quantity":6,"unit":"oz","section":"protein"},{"name":"Smoked paprika","quantity":1,"unit":"tsp","section":"pantry"},{"name":"Cooked rice","quantity":0.75,"unit":"cup","section":"grains"},{"name":"Canned black beans","quantity":0.5,"unit":"cup","section":"protein"},{"name":"Corn kernels","quantity":0.5,"unit":"cup","section":"frozen"},{"name":"Salsa","quantity":0.25,"unit":"cup","section":"pantry"},{"name":"Romaine lettuce","quantity":1,"unit":"cup","section":"produce"}]'::jsonb, array['Crumble the tofu and pan-fry with smoked paprika, cumin, and salt until browned.', 'Warm the beans and corn.', 'Assemble over rice and lettuce, topped with salsa.'], 'Keeps 3 days refrigerated.', null, 'active'),
('Miso Ginger Soba with Roasted Vegetables', 'lunch', 'japanese', 446, 18, 62, 14, 8, 10, 20, 1, array['vegan', 'vegetarian'], array['wheat', 'soybeans', 'sesame'], '[{"name":"Soba noodles","quantity":2.5,"unit":"oz","section":"grains"},{"name":"White miso paste","quantity":1,"unit":"tbsp","section":"pantry"},{"name":"Fresh ginger","quantity":1,"unit":"tbsp","section":"produce"},{"name":"Broccoli florets","quantity":1,"unit":"cup","section":"produce"},{"name":"Red bell pepper","quantity":1,"unit":"each","section":"produce"},{"name":"Sesame oil","quantity":1,"unit":"tsp","section":"pantry"},{"name":"Rice vinegar","quantity":1,"unit":"tbsp","section":"pantry"}]'::jsonb, array['Roast the broccoli and pepper at 425°F for 15-18 minutes.', 'Cook the soba and rinse under cold water.', 'Whisk miso, grated ginger, vinegar, and sesame oil; toss everything together.'], 'Keeps 3 days refrigerated, eaten cold or reheated.', null, 'active'),
('Tofu Veggie Scramble', 'breakfast', 'american', 306, 22, 14, 18, 5, 5, 10, 1, array['vegan', 'vegetarian', 'gluten-free', 'high-protein', 'quick'], array['soybeans'], '[{"name":"Extra-firm tofu","quantity":6,"unit":"oz","section":"protein"},{"name":"Baby spinach","quantity":1.5,"unit":"cups","section":"produce"},{"name":"Cherry tomatoes","quantity":0.5,"unit":"cup","section":"produce"},{"name":"Olive oil","quantity":2,"unit":"tsp","section":"pantry"},{"name":"Turmeric","quantity":0.25,"unit":"tsp","section":"pantry"},{"name":"Nutritional yeast","quantity":1,"unit":"tbsp","section":"pantry"}]'::jsonb, array['Crumble the tofu into a hot oiled pan with turmeric and salt.', 'Cook 5-6 minutes until it starts to color, then fold in tomatoes and spinach.', 'Finish with nutritional yeast and black pepper.'], 'Best fresh; keeps 2 days refrigerated.', null, 'active'),
('Peanut Butter Banana Overnight Oats', 'breakfast', 'american', 412, 15, 52, 16, 9, 5, 0, 1, array['vegan', 'vegetarian', 'make-ahead', 'quick'], array['peanuts'], '[{"name":"Rolled oats","quantity":0.5,"unit":"cup","section":"grains"},{"name":"Unsweetened oat milk","quantity":0.75,"unit":"cup","section":"pantry"},{"name":"Peanut butter","quantity":1,"unit":"tbsp","section":"pantry"},{"name":"Banana","quantity":1,"unit":"each","section":"produce"},{"name":"Chia seeds","quantity":1,"unit":"tsp","section":"pantry"},{"name":"Maple syrup","quantity":1,"unit":"tsp","section":"pantry"},{"name":"Cinnamon","quantity":0.25,"unit":"tsp","section":"pantry"}]'::jsonb, array['Stir everything except the banana together in a jar.', 'Refrigerate overnight.', 'Top with sliced banana in the morning.'], 'Keeps 3 days refrigerated (add banana fresh).', null, 'active'),
('Chia Berry Coconut Bowl', 'breakfast', 'american', 372, 10, 38, 20, 15, 5, 0, 1, array['vegan', 'vegetarian', 'gluten-free', 'make-ahead'], array[]::text[], '[{"name":"Chia seeds","quantity":3,"unit":"tbsp","section":"pantry"},{"name":"Light coconut milk","quantity":0.75,"unit":"cup","section":"pantry"},{"name":"Mixed berries","quantity":1,"unit":"cup","section":"frozen"},{"name":"Maple syrup","quantity":2,"unit":"tsp","section":"pantry"},{"name":"Shredded coconut","quantity":1,"unit":"tbsp","section":"pantry"}]'::jsonb, array['Whisk chia seeds into the coconut milk with maple syrup; refrigerate at least 2 hours or overnight.', 'Top with berries and shredded coconut.'], 'Keeps 3 days refrigerated.', null, 'active'),
('Paneer Tikka Bowl', 'dinner', 'indian', 536, 28, 52, 24, 6, 15, 20, 1, array['vegetarian', 'gluten-free', 'high-protein'], array['milk'], '[{"name":"Paneer","quantity":4,"unit":"oz","section":"dairy"},{"name":"Plain yogurt","quantity":2,"unit":"tbsp","section":"dairy"},{"name":"Tikka spice blend","quantity":1,"unit":"tbsp","section":"pantry"},{"name":"Cooked basmati rice","quantity":1,"unit":"cup","section":"grains"},{"name":"Red bell pepper","quantity":1,"unit":"each","section":"produce"},{"name":"Red onion","quantity":0.5,"unit":"each","section":"produce"},{"name":"Cilantro","quantity":0.25,"unit":"cup","section":"produce"}]'::jsonb, array['Toss paneer cubes, pepper, and onion in yogurt and tikka spices; marinate 10 minutes.', 'Roast at 450°F (or broil) for 12-15 minutes until charred at the edges.', 'Serve over rice with cilantro.'], 'Keeps 3 days refrigerated.', null, 'active'),
('Caprese Baked Gnocchi', 'dinner', 'italian', 522, 22, 68, 18, 6, 10, 25, 1, array['vegetarian'], array['milk', 'wheat'], '[{"name":"Potato gnocchi","quantity":6,"unit":"oz","section":"grains"},{"name":"Marinara sauce","quantity":0.75,"unit":"cup","section":"pantry"},{"name":"Fresh mozzarella","quantity":2,"unit":"oz","section":"dairy"},{"name":"Cherry tomatoes","quantity":0.5,"unit":"cup","section":"produce"},{"name":"Fresh basil","quantity":0.25,"unit":"cup","section":"produce"},{"name":"Olive oil","quantity":1,"unit":"tsp","section":"pantry"}]'::jsonb, array['Toss gnocchi with marinara and tomatoes in a small baking dish.', 'Top with torn mozzarella and bake at 425°F for 20-25 minutes until bubbling.', 'Finish with basil and a drizzle of olive oil.'], 'Keeps 2 days refrigerated.', null, 'active'),
('Veggie Egg Fried Rice', 'dinner', 'chinese', 494, 21, 62, 18, 6, 10, 12, 1, array['vegetarian', 'quick'], array['eggs', 'soybeans', 'wheat', 'sesame'], '[{"name":"Cooked day-old rice","quantity":1.25,"unit":"cups","section":"grains"},{"name":"Eggs","quantity":2,"unit":"each","section":"dairy"},{"name":"Frozen peas and carrots","quantity":0.75,"unit":"cup","section":"frozen"},{"name":"Soy sauce","quantity":1,"unit":"tbsp","section":"pantry"},{"name":"Sesame oil","quantity":1,"unit":"tsp","section":"pantry"},{"name":"Scallions","quantity":2,"unit":"each","section":"produce"},{"name":"Neutral oil","quantity":2,"unit":"tsp","section":"pantry"}]'::jsonb, array['Scramble the eggs in a hot wok and set aside.', 'Stir-fry the vegetables, then the rice, pressing it against the wok to crisp.', 'Return the eggs, season with soy sauce and sesame oil, and finish with scallions.'], 'Keeps 3 days refrigerated.', null, 'active');
